args <- commandArgs(TRUE)
stopifnot(length(args)>=2, getRversion()==numeric_version('4.5.1'))
library(jsonlite)
inp <- fromJSON(args[1],simplifyVector=FALSE)
num <- function(x) vapply(x,function(z) if(is.null(z)||is.logical(z)||length(z)!=1||trimws(as.character(z))=='') NA_real_ else suppressWarnings(as.numeric(z)),numeric(1))
mat <- function(x) do.call(rbind,lapply(x,num))
clean <- function(x) {x<-num(x);x[is.finite(x)]}
summarize <- function(x) {raw<-num(x);x<-raw[is.finite(raw)];n<-length(x);if(!n)return(list(n=0,missing=length(raw),mean=NA_real_,median=NA_real_,min=NA_real_,max=NA_real_,variancePopulation=NA_real_,varianceSample=NA_real_,sdPopulation=NA_real_,sdSample=NA_real_));vp<-mean((x-mean(x))^2);vs<-if(n>1)var(x)else NA_real_;list(n=n,missing=length(raw)-n,mean=mean(x),median=median(x),min=min(x),max=max(x),variancePopulation=vp,varianceSample=vs,sdPopulation=sqrt(vp),sdSample=sqrt(vs))}
# Independent exact average over all permutations within X ties. Small fixtures only.
perms <- function(x) {if(length(x)<=1)return(list(x));unlist(lapply(seq_along(x),function(j)lapply(perms(x[-j]),function(t)c(x[j],t))),recursive=FALSE)}
xi <- function(x,y){n<-length(x);if(n<3)return(NA_real_);r<-rank(y,ties.method='max');l<-n-rank(y,ties.method='min')+1;den<-2*sum(l*(n-l));if(den==0)return(NA_real_);blocks<-split(seq_len(n),factor(x,levels=sort(unique(x))));orders<-list(integer(0));for(block in blocks)orders<-unlist(lapply(orders,function(old)lapply(perms(block),function(z)c(old,z))),recursive=FALSE);mean(vapply(orders,function(order)1-n*sum(abs(diff(r[order])))/den,numeric(1)))}
correlations<-lapply(inp$correlations,function(c){a<-num(c$a);b<-num(c$b);n<-min(length(a),length(b));a<-a[seq_len(n)];b<-b[seq_len(n)];ok<-is.finite(a)&is.finite(b);a<-a[ok];b<-b[ok];z<-list(name=c$name,n=length(a),pearson=if(length(a)>=3)suppressWarnings(cor(a,b))else NA_real_,spearman=if(length(a)>=3)suppressWarnings(cor(a,b,method='spearman'))else NA_real_);if(isTRUE(c$xi)){z$chatterjee<-xi(a,b);z$chatterjeeReverse<-xi(b,a)};z})
pairs<-lapply(inp$pairs,function(c){a<-num(c$a);b<-num(c$b);t<-t.test(a,b,var.equal=FALSE);u<-suppressWarnings(wilcox.test(a,b,exact=FALSE,correct=FALSE));ks<-suppressWarnings(ks.test(a,b,exact=FALSE));ne<-length(a)*length(b)/(length(a)+length(b));lambda<-(sqrt(ne)+.12+.11/sqrt(ne))*unname(ks$statistic);stephens<-if(lambda<.3)1 else max(0,min(1,sum(2*(-1)^((1:100)-1)*exp(-2*(1:100)^2*lambda^2))));pooled<-sqrt(((length(a)-1)*var(a)+(length(b)-1)*var(b))/(length(a)+length(b)-2));list(name=c$name,welch=list(statistic=unname(t$statistic),df=unname(t$parameter),p=t$p.value,ci95=as.vector(t$conf.int),effect=(mean(a)-mean(b))/pooled),mannWhitney=list(statistic=unname(u$statistic),p=u$p.value,effect=1-2*unname(u$statistic)/(length(a)*length(b))),ks=list(statistic=unname(ks$statistic),p=stephens,rAsymptoticP=ks$p.value,rExactP=if(length(a)*length(b)<10000)suppressWarnings(ks.test(a,b,exact=TRUE))$p.value else NA_real_))})
groups<-lapply(inp$groups,function(c){g<-lapply(c$groups,num);v<-unlist(g);n<-length(v);k<-length(g);h<-kruskal.test(g);means<-vapply(g,mean,numeric(1));sizes<-lengths(g);ssb<-sum(sizes*(means-mean(v))^2);sst<-sum((v-mean(v))^2);msw<-(sst-ssb)/(n-k);list(name=c$name,kruskal=list(statistic=unname(h$statistic),df=unname(h$parameter),p=h$p.value,effect=unname(h$statistic)*(n+1)/(n*n-1)),comparison=list(groups=lapply(seq_along(g),function(i)list(group=paste0('g',i),n=length(g[[i]]),mean=mean(g[[i]]),sd=sd(g[[i]]))),overall=list(n=n,mean=mean(v),sd=sd(v)),etaSquared=ssb/sst,omegaSquared=(ssb-(k-1)*msw)/(sst+msw)))})
contingencies<-lapply(inp$contingencies,function(c){m<-mat(c$counts);t<-suppressWarnings(chisq.test(m,correct=FALSE));list(name=c$name,statistic=unname(t$statistic),df=unname(t$parameter),p=t$p.value,effect=sqrt(unname(t$statistic)/(sum(m)*(min(dim(m))-1))))})
clusters<-lapply(inp$clusters,function(c){x<-mat(c$rows);fits<-lapply(c$initialCenters,function(centers)kmeans(x,centers=mat(centers),iter.max=300,algorithm='Lloyd'));winner<-which.min(vapply(fits,function(f)f$tot.withinss,numeric(1)));fit<-fits[[winner]];list(name=c$name,selectedStart=winner-1,allInertias=vapply(fits,function(f)f$tot.withinss,numeric(1)),cluster=fit$cluster-1,centers=fit$centers,inertia=fit$tot.withinss,iterations=vapply(fits,function(f)f$iter,numeric(1)))})
pca<-list()
for(c in inp$pca)for(missing in c('complete','mean','median'))for(standardize in c(FALSE,TRUE)){
 if(!is.null(c$contracts)&&!any(vapply(c$contracts,function(contract)contract$missing==missing&&contract$standardize==standardize,logical(1))))next
 x<-mat(if(missing=='complete')c$train else c$trainMissing);h<-mat(if(missing=='complete')c$holdout else c$holdoutMissing)
 fills<-if(missing=='complete')rep(NA_real_,ncol(x))else apply(x,2,if(missing=='mean')mean else median,na.rm=TRUE)
 if(missing!='complete')for(j in seq_len(ncol(x))){x[is.na(x[,j]),j]<-fills[j];h[is.na(h[,j]),j]<-fills[j]}
 center<-colMeans(x);scale<-if(standardize)sqrt(colMeans(sweep(x,2,center)^2))else rep(1,ncol(x));fit<-prcomp(x,center=center,scale.=scale)
 pca[[length(pca)+1]]<-list(name=c$name,missing=missing,standardize=standardize,center=center,scale=scale,replacements=fills,eigenvalues=fit$sdev^2*(nrow(x)-1)/nrow(x),components=fit$rotation,scores=fit$x,holdout=predict(fit,h))
}
sha<-strsplit(system2('sha256sum',args[1],stdout=TRUE),' ')[[1]][1]
result<-list(schema=1,provenance=list(R=R.version.string,platform=R.version$platform,stats=as.character(packageVersion('stats')),jsonlite=as.character(packageVersion('jsonlite')),inputSha256=sha,generatorSha256=strsplit(system2('sha256sum',sub('^--file=','',grep('^--file=',commandArgs(FALSE),value=TRUE)[1]),stdout=TRUE),' ')[[1]][1],image=Sys.getenv('REFERENCE_IMAGE_ID'),conventions=inp$conventions,xi='Independent R exact predictor-tie permutation average of the paper formula, not a canonical-package call'),descriptions=lapply(inp$descriptions,function(c)c(list(name=c$name),summarize(c$values))),correlations=correlations,pairs=pairs,groups=groups,contingencies=contingencies,clusters=clusters,pca=pca)
write_json(result,args[2],auto_unbox=TRUE,pretty=TRUE,digits=17,na='null',null='null',matrix='rowmajor')
